import sys

def main():
    s = sys.stdin.readline().strip()

    pairs = {')': '(', ']': '[', '>': '<'}
    opens = set(pairs.values())
    stack = []

    for ch in s:
        if ch in opens:
            stack.append(ch)
        else:
            if not stack or stack[-1] != pairs[ch]:
                print("No")
                return
            stack.pop()

    print("Yes" if not stack else "No")

if __name__ == "__main__":
    main()
